import type { AgentID } from '../shared/agent-id';
import type { Config } from '../shared/config';
import { isRecord } from '../shared/report';

// What the overlay needs to know per agent to label a row: the readable
// name, and the tier-alias map a gateway's env configures.
export interface AgentMetadata {
  readonly labels: Readonly<Record<AgentID, string>>;

  // Per agent id, the alias-to-model mapping an `agents.list` entry
  // carries; absent for agents that take models by name only.
  readonly models: Readonly<Record<AgentID, Readonly<Record<string, string>>>>;
}

const BUILT_IN_LABELS: Readonly<Record<AgentID, string>> = {
  claude: 'Claude',
  grok: 'Grok',
  codex: 'Codex',
};

/**
 * The labels and model aliases the overlay draws with, resolved from the
 * config a client reads at start and the daemon's `agents.list` answer once
 * it arrives. The answer wins, so a backend the daemon registers under a
 * stand-in adapter still lists under its own name; the config alone covers
 * the window before the answer lands.
 */
export function resolveAgentMetadata(config: Config, listed: unknown): AgentMetadata {
  const labels: Record<AgentID, string> = { ...BUILT_IN_LABELS };
  const models: Record<AgentID, Readonly<Record<string, string>>> = {};

  for (const gateway of config.gateways) {
    labels[gateway.id] = gateway.label;
  }

  if (isRecord(listed) && Array.isArray(listed['agents'])) {
    for (const entry of listed['agents']) {
      if (!isRecord(entry) || typeof entry['id'] !== 'string') {
        continue;
      }

      if (typeof entry['label'] === 'string' && entry['label'] !== '') {
        labels[entry['id']] = entry['label'];
      }

      if (isRecord(entry['models'])) {
        const aliases: Record<string, string> = {};

        for (const [alias, model] of Object.entries(entry['models'])) {
          if (typeof model === 'string') {
            aliases[alias] = model;
          }
        }

        models[entry['id']] = aliases;
      }
    }
  }

  return { labels, models };
}

import { expect, test } from 'bun:test';
import { parseConfig } from '../shared/config';
import { resolveAgentMetadata } from './resolve-agent-metadata';

// The config every test starts from: no gateways, so each case adds the one
// it is about.
function buildConfig(gateways: unknown): ReturnType<typeof parseConfig> {
  return parseConfig({ gateways });
}

test('it labels the built-in agents by name', () => {
  const meta = resolveAgentMetadata(buildConfig({}), {});

  expect(meta.labels['claude']).toBe('Claude');
  expect(meta.labels['grok']).toBe('Grok');
  expect(meta.labels['codex']).toBe('Codex');
});

test('it labels a configured gateway by its configured label', () => {
  const meta = resolveAgentMetadata(
    buildConfig({ zai: { label: 'GLM (z.ai)', baseURL: 'https://llm.example.com/api/anthropic' } }),
    {},
  );

  expect(meta.labels['zai']).toBe('GLM (z.ai)');
});

test('it labels a gateway without a label by its id', () => {
  const meta = resolveAgentMetadata(
    buildConfig({ kimi: { baseURL: 'https://example.invalid/api/anthropic' } }),
    {},
  );

  expect(meta.labels['kimi']).toBe('kimi');
});

test('it lets the agents.list answer win over the config label', () => {
  const meta = resolveAgentMetadata(
    buildConfig({ zai: { label: 'GLM (z.ai)', baseURL: 'https://llm.example.com/api/anthropic' } }),
    { agents: [{ id: 'zai', label: 'GLM staged' }] },
  );

  expect(meta.labels['zai']).toBe('GLM staged');
});

test('it keeps the config label when the answer entry carries none', () => {
  const meta = resolveAgentMetadata(
    buildConfig({ zai: { label: 'GLM (z.ai)', baseURL: 'https://llm.example.com/api/anthropic' } }),
    { agents: [{ id: 'zai' }] },
  );

  expect(meta.labels['zai']).toBe('GLM (z.ai)');
});

test('it reads an agents.list model alias map', () => {
  const meta = resolveAgentMetadata(buildConfig({}), {
    agents: [{ id: 'zai', models: { opus: 'glm-5.3' } }],
  });

  expect(meta.models['zai']).toStrictEqual({ opus: 'glm-5.3' });
});

test('it keeps the non-string values of an agents.list model map out', () => {
  const meta = resolveAgentMetadata(buildConfig({}), {
    agents: [{ id: 'zai', models: { opus: 7, sonnet: 'glm-5.2' } }],
  });

  expect(meta.models['zai']).toStrictEqual({ sonnet: 'glm-5.2' });
});

test('it reports no model map for an agent whose answer entry has none', () => {
  const meta = resolveAgentMetadata(buildConfig({}), { agents: [{ id: 'claude' }] });

  expect(meta.models['claude']).toBeUndefined();
});

test('it falls back to the config alone when the answer holds no agents array', () => {
  const meta = resolveAgentMetadata(
    buildConfig({ zai: { label: 'GLM (z.ai)', baseURL: 'https://llm.example.com/api/anthropic' } }),
    'not an answer',
  );

  expect(meta.labels['zai']).toBe('GLM (z.ai)');
  expect(meta.models['zai']).toBeUndefined();
});

// The glyph, unread, and pin cells that lead every row, plus the one space
// before the first body column.
const PREFIX_WIDTH = 4;

export interface OverlayColumnPlan {
  readonly nameWidth: number;

  // The directory column of the flat view; 0 in the grouped view and
  // whenever width pressure crowds it out.
  readonly dirWidth: number;

  // 0 while only one target is available, so the column stays hidden.
  readonly targetWidth: number;
  readonly harnessWidth: number;

  // 0 when no visible session runs an explicit model.
  readonly modelWidth: number;
  readonly lifecycleWidth: number;
  readonly eventWidth: number;
}

export interface OverlayColumnInput {
  // The width inside the overlay box: the box width less its borders and
  // padding.
  readonly innerWidth: number;

  readonly grouped: boolean;

  // Whether more than one execution target is available to spawn on.
  readonly showTarget: boolean;

  // The longest label each column would draw over the visible sessions;
  // 0 for a column with nothing to show.
  readonly targetMax: number;
  readonly harnessMax: number;
  readonly modelMax: number;
}

// How much pressure it takes to crowd a column out, from first to go to
// last: the flat view's directory, then the model and the last event, then
// the harness, target, and name, with the lifecycle text held longest.
const SHRINK_ORDER = ['dir', 'model', 'event', 'harness', 'target', 'name', 'lifecycle'] as const;

type ShrinkKey = (typeof SHRINK_ORDER)[number];

const PREFERRED: Readonly<Record<ShrinkKey, number>> = {
  dir: 18,
  model: 14,
  event: 512,
  harness: 14,
  target: 14,
  name: 16,
  lifecycle: 9,
};

// The least each column keeps while any width remains to take: the name,
// target, and harness stay legible after the model, event, and directory
// have given way.
const FLOOR: Readonly<Record<ShrinkKey, number>> = {
  dir: 0,
  model: 0,
  event: 0,
  harness: 3,
  target: 3,
  name: 6,
  lifecycle: 9,
};

/**
 * The column widths a session row draws with. Each column starts at the
 * shorter of its preferred width and the longest value it would draw; while
 * the row outgrows the box, the narrowest-pressure column above its floor
 * gives up a cell at a time in the order above, so the model and the last
 * event shrink first and the name, target, and harness last.
 */
export function planOverlayColumns(input: Readonly<OverlayColumnInput>): OverlayColumnPlan {
  const widths: Record<ShrinkKey, number> = {
    dir: input.grouped ? 0 : PREFERRED.dir,
    model: capContent(input.modelMax, PREFERRED.model),
    event: PREFERRED.event,
    harness: capContent(input.harnessMax, PREFERRED.harness),
    target: input.showTarget ? Math.max(FLOOR.target, capContent(input.targetMax, PREFERRED.target)) : 0,
    name: PREFERRED.name,
    lifecycle: PREFERRED.lifecycle,
  };

  shrink(widths, input);

  return {
    nameWidth: widths.name,
    dirWidth: widths.dir,
    targetWidth: widths.target,
    harnessWidth: widths.harness,
    modelWidth: widths.model,
    lifecycleWidth: widths.lifecycle,
    eventWidth: widths.event,
  };
}

// A column with nothing to draw keeps no width; otherwise it takes the
// shorter of its preferred width and its longest value.
function capContent(contentMax: number, preferred: number): number {
  return contentMax <= 0 ? 0 : Math.min(contentMax, preferred);
}

function shrink(widths: Record<ShrinkKey, number>, input: Readonly<OverlayColumnInput>): void {
  while (totalWidth(widths) > input.innerWidth) {
    const giver = SHRINK_ORDER.map((key) => ({ key, width: widths[key] }))
      .filter((col) => col.width > FLOOR[col.key])
      .sort((a, b) => SHRINK_ORDER.indexOf(a.key) - SHRINK_ORDER.indexOf(b.key))[0];

    if (giver === undefined) {
      return;
    }

    widths[giver.key] -= 1;
  }
}

// The prefix plus every column and one space between the columns that still
// draw, so a column crowded to nothing takes its gap with it.
function totalWidth(widths: Readonly<Record<ShrinkKey, number>>): number {
  const visible = SHRINK_ORDER.filter((key) => widths[key] > 0);

  return PREFIX_WIDTH + visible.reduce((sum, key) => sum + widths[key], 0) + Math.max(0, visible.length - 1);
}

// The glyph, unread, and pin cells that lead every row, plus the one space
// before the first body column.
const PREFIX_WIDTH = 4;

// The last-event column's soft width once the rest has claimed its share;
// whatever width remains after shrinking goes back to it.
const EVENT_BASE_WIDTH = 4;

export interface OverlayColumnPlan {
  readonly nameWidth: number;

  // The directory column of the flat view; 0 in the grouped view and
  // whenever width pressure crowds it out.
  readonly dirWidth: number;

  // 0 while only one target is available, so the column stays hidden.
  readonly targetWidth: number;
  readonly harnessWidth: number;

  // 0 when no visible session runs an explicit model.
  readonly modelWidth: number;
  readonly lifecycleWidth: number;
  readonly eventWidth: number;
}

export interface OverlayColumnInput {
  // The width inside the overlay box: the box width less its borders and
  // padding.
  readonly innerWidth: number;

  readonly grouped: boolean;

  // Whether more than one execution target is available to spawn on.
  readonly showTarget: boolean;

  // The longest label each column would draw over the visible sessions;
  // 0 for a column with nothing to show.
  readonly targetMax: number;
  readonly harnessMax: number;
  readonly modelMax: number;
}

type ColumnKey = 'dir' | 'model' | 'event' | 'harness' | 'target' | 'name' | 'lifecycle';

// How much pressure it takes to crowd a column out, from first to go to
// last: the flat view's directory, then the model and the last event, then
// the harness, the target, and the name, with the lifecycle text held
// longest.
const SHRINK_ORDER: readonly ColumnKey[] = [
  'dir',
  'model',
  'event',
  'harness',
  'target',
  'name',
  'lifecycle',
];

const PREFERRED: Readonly<Record<ColumnKey, number>> = {
  dir: 18,
  model: 14,
  event: EVENT_BASE_WIDTH,
  harness: 14,
  target: 14,
  name: 16,
  lifecycle: 9,
};

// The least each column keeps while any width remains to take: the name,
// target, and harness stay legible after the directory, model, and last
// event have given way.
const FLOOR: Readonly<Record<ColumnKey, number>> = {
  dir: 0,
  model: 0,
  event: 0,
  harness: 3,
  target: 3,
  name: 6,
  lifecycle: 9,
};

/**
 * The column widths a session row draws with. Each column starts at the
 * shorter of its preferred width and the longest value it would draw; while
 * the row outgrows the box, the column under the least pressure that still
 * holds its floor gives up a cell at a time in the order above, so the
 * model and the last event shrink first and the name, target, and harness
 * last. Whatever width is left over after the row fits goes to the last
 * event.
 */
export function planOverlayColumns(input: Readonly<OverlayColumnInput>): OverlayColumnPlan {
  const widths: Record<ColumnKey, number> = {
    dir: input.grouped ? 0 : PREFERRED.dir,
    model: capContent(input.modelMax, PREFERRED.model),
    event: PREFERRED.event,
    harness: capContent(input.harnessMax, PREFERRED.harness),
    target: input.showTarget ? capContent(input.targetMax, PREFERRED.target) : 0,
    name: PREFERRED.name,
    lifecycle: PREFERRED.lifecycle,
  };

  shrink(widths, input.innerWidth, (key) => FLOOR[key]);
  shrink(widths, input.innerWidth, () => 0);
  widths.event += Math.max(0, input.innerWidth - totalWidth(widths));

  return {
    nameWidth: widths.name,
    dirWidth: widths.dir,
    targetWidth: widths.target,
    harnessWidth: widths.harness,
    modelWidth: widths.model,
    lifecycleWidth: widths.lifecycle,
    eventWidth: widths.event,
  };
}

// A column with nothing to draw keeps no width; otherwise it takes the
// shorter of its preferred width and its longest value.
function capContent(contentMax: number, preferred: number): number {
  return contentMax <= 0 ? 0 : Math.min(contentMax, preferred);
}

function shrink(
  widths: Record<ColumnKey, number>,
  innerWidth: number,
  floorOf: (key: ColumnKey) => number,
): void {
  while (totalWidth(widths) > innerWidth) {
    const giver = SHRINK_ORDER.find((key) => widths[key] > floorOf(key));

    if (giver === undefined) {
      return;
    }

    widths[giver] -= 1;
  }
}

// The prefix plus every column and one space between the columns that still
// draw, so a column crowded to nothing takes its gap with it.
function totalWidth(widths: Readonly<Record<ColumnKey, number>>): number {
  const visible = SHRINK_ORDER.filter((key) => widths[key] > 0);

  return (
    PREFIX_WIDTH +
    visible.reduce((sum, key) => sum + widths[key], 0) +
    Math.max(0, visible.length - 1)
  );
}

